class EvolutionTracker:
    def __init__(self):
        self.performance_log = []
        self.knowledge_snapshots = []

    def log_generation(self, metrics):
        """记录每代进化指标"""
        generation = {
            "timestamp": datetime.now(),
            "performance": metrics["accuracy"],
            "knowledge_size": metrics["kb_size"],
            "parameters": self._capture_params()
        }
        self.performance_log.append(generation)

    def calculate_evolution_rate(self):
        """计算进化速率"""
        if len(self.performance_log) < 2:
            return 0.0

        recent = self.performance_log[-1]["performance"]
        baseline = self.performance_log[0]["performance"]

        return (recent - baseline) / baseline * 100
